# -*- coding: utf-8 -*-
# Contenido del instructivo: lista de capítulos. Cada bloque: ("p", texto) ("h3", t) ("steps", [..]) ("fig", img, pie, [leyenda..]) ("tip", t) ("warn", t) ("note", t) ("ul", [..]) ("table", [cab], [[fila]..])
CH = []
def ch(title, *blocks): CH.append((title, list(blocks)))

ch("Introducción",
 ("p", "<b>OPEN SOURCE PARIZ</b> es un portal que se abre en el navegador y permite manejar un módulo de radio <b>LoRa Mesh</b> (por ejemplo un Heltec V3 con firmware 2.8) desde la computadora o el celular. Con él podés escribir y recibir mensajes por radio, ver a los demás nodos en una lista y en un mapa, configurar el equipo, pedir telemetría y, cuando hay Internet, sumar servidores MQTT para que los mensajes también viajen por la red."),
 ("p", "El portal está pensado para funcionar <b>sin Internet</b>: la radio LoRa funciona siempre y todo lo que se ve en pantalla sale del propio nodo. Cuando hay conexión a Internet, el portal se conecta además a uno o varios servidores MQTT (hasta seis a la vez)."),
 ("h3", "Qué vas a poder hacer"),
 ("ul", ["Conectar tu nodo por <b>cable USB</b>, por <b>Bluetooth</b> o por la <b>red WiFi / LAN</b>, y guardar las conexiones para volver a usarlas con un clic.",
         "Enviar mensajes a un canal o a un nodo en particular, con <b>reintentos automáticos</b> y el botón <b>Reenviar mensaje</b> si no se entregó.",
         "<b>Programar</b> un mensaje para una hora determinada, a un nodo (con buscador) o a un grupo de reenvío.",
         "Usar el botón rojo de <b>EMERGENCIAS</b>, que envía la misma alerta a todos los canales con teléfono, país, frecuencia y coordenada opcionales.",
         "Filtrar la lista de nodos por alcance, estado y función, y marcar nodos <b>favoritos</b>.",
         "Ver el mapa con la altura sobre el nivel del mar y los saltos de cada nodo.",
         "Elegir un <b>tono distinto</b> para cada tipo de aviso.",
         "Ver de un vistazo qué nodos están bien, cuáles tienen batería o señal débil y cuáles dieron una alerta o se cayeron (semáforo en el mapa y en la lista).",
         "Dibujar la <b>topología</b>: quién se escucha directamente, qué rutas se conocen y quién depende de repetidores, separando lo medido de lo inferido.",
         "Filtrar mensajes y eventos críticos por rango de horas y exportarlos a <b>PDF o Excel</b> para el libro de guardia y las actas.",
         "<b>Responder y reaccionar</b> a los mensajes, y ver la <b>ficha completa</b> de cada nodo.",
         "Recibir <b>avisos del celular o de la PC</b>, pasarle al nodo la <b>ubicación del celular</b>, compartir canales con un <b>código QR</b> y guardar <b>zonas de mapa</b> para usar sin conexión.",
         "Configurar el nodo (radio, canales, dispositivo, módulos), hacer respaldos y exportar datos."]),
 ("warn", "<b>Seguridad.</b> El botón de EMERGENCIAS envía un mensaje por radio LoRa: llega solamente si hay otro nodo o un repetidor al alcance. <b>No reemplaza</b> a los servicios de emergencia (911 / 105 / 100) ni a un equipo de comunicaciones de emergencia. Probá siempre el sistema antes de depender de él."),
)

ch("Requisitos y primeros pasos",
 ("h3", "Qué necesitás"),
 ("table", ["Elemento", "Detalle"], [
   ["Nodo LoRa Mesh", "Un módulo con firmware 2.x (se probó con Heltec V3, firmware 2.8.1). Para Bluetooth o WiFi el nodo debe tener esas funciones activadas."],
   ["Navegador", "<b>Google Chrome, Microsoft Edge, Brave u Opera</b> en una PC (USB y Bluetooth). En Android sirve Chrome para Bluetooth y red. Firefox y Safari no permiten USB ni Bluetooth."],
   ["Archivo del portal", "<b>portal-lora-mesh.html</b>: es un único archivo; no hay que instalar nada."],
   ["Archivos opcionales", "<b>puente-mqtt.py</b> e <b>iniciar-puente.bat</b> (solo para usar servidores MQTT que no ofrecen WebSocket; ver el capítulo de Internet y MQTT)."],
   ["Cable USB", "Un cable <b>de datos</b>. Muchos cables son solo de carga y no funcionan."]]),
 ("h3", "Abrir el portal"),
 ("steps", [
   "Guardá <b>portal-lora-mesh.html</b> en una carpeta de tu computadora (por ejemplo, Descargas o el Escritorio).",
   "Hacé doble clic sobre el archivo: se abre en tu navegador predeterminado. Si ese navegador es Firefox o Safari, abrilo con Chrome, Edge o Brave (clic derecho → <i>Abrir con</i>).",
   "En <b>Brave</b>, para usar Bluetooth escribí <b>brave://flags/#brave-web-bluetooth-api</b> en la barra de direcciones, activá la opción y reiniciá el navegador.",
   "La primera pantalla te pide conectar el nodo. Si todavía no tenés el nodo a mano, podés tocar <b>Ver modo demo (sin nodo)</b> para recorrer el portal con datos de ejemplo."]),
 ("note", "<b>Tus datos quedan en tu navegador.</b> Las conexiones guardadas, los mensajes, los favoritos y los ajustes se guardan solo en el navegador de esta computadora. Si abrís el portal en otro navegador o en otro equipo, vas a empezar de cero."),
)

ch("Conectar el nodo",
 ("p", "Al abrir el portal aparece la pantalla de conexión. Elegí cómo está conectado tu nodo:"),
 ("fig", "01_conectar", "Pantalla de conexión", ["<b>USB (cable):</b> el nodo conectado a un puerto USB de la computadora.", "<b>Bluetooth:</b> conexión inalámbrica de corto alcance (el navegador debe soportar Bluetooth web).", "<b>Red (WiFi / LAN):</b> el nodo está en tu red (WiFi o Ethernet) y se lo busca por su dirección IP."]),
 ("h3", "Conexión por USB"),
 ("steps", [
   "Conectá el nodo a la computadora con un cable de datos y cerrá cualquier otro programa que use el puerto (otras aplicaciones de la red LoRa, monitores serie, etc.).",
   "Tocá <b>USB (cable)</b>. El navegador abre una ventana con los puertos disponibles.",
   "Elegí el puerto del nodo y tocá <b>Conectar</b>. Esperá unos segundos: el portal descarga la configuración y muestra el aviso <b>Nodo configurado y listo</b>."]),
 ("h3", "Conexión por Bluetooth"),
 ("steps", [
   "En el nodo, activá Bluetooth y asegurate de que no esté conectado a otro teléfono o computadora.",
   "Tocá <b>Bluetooth</b> y elegí el nodo de la lista que muestra el navegador.",
   "Si el nodo lo pide, escribí el PIN que aparece en su pantalla."]),
 ("h3", "Conexión por red (WiFi / LAN)"),
 ("steps", [
   "Verificá que el nodo tenga WiFi o Ethernet configurado y anotá su <b>dirección IP</b> (por ejemplo 192.168.1.50).",
   "La computadora debe estar en la <b>misma red</b> que el nodo.",
   "Tocá <b>Red (WiFi / LAN)</b>, escribí la dirección IP y, si el nodo usa HTTPS, marcá la opción correspondiente. Tocá <b>Conectar</b>."]),
 ("fig", "02_dialogo_red", "Ventana de conexión por red", []),
 ("h3", "¿No sabés la dirección IP? Buscar el nodo en la red"),
  ("p", "Dentro de la misma ventana, el bloque <b>Buscar el nodo en la red</b> recorre las direcciones de tu red y te muestra cuáles son nodos. Trabaja en <b>dos pasadas</b>: primero ve rápido qué direcciones responden algo y después, solo sobre esas pocas, confirma cuáles son nodos dándoles más tiempo. Así no se pierde un nodo que tarde en contestar y el barrido no demora minutos."),
 ("fig", "02b_buscar_red", "Búsqueda del nodo en la red", []),
 ("h3", "Cómo se escribe la red"),
 ("p", "Es el error más común y por eso conviene detenerse acá: en <b>Redes a revisar</b> van los <b>tres primeros números</b> de la dirección, no la dirección completa."),
 ("table", ["Lo que escribís", "Qué revisa"], [
   ["<b>192.168.1</b>", "Toda la red: de 192.168.1.1 a 192.168.1.254. <b>Es lo normal.</b>"],
   ["192.168.1.*", "Lo mismo."],
   ["192.168.1.0/24", "Lo mismo."],
   ["192.168.1.10-40", "Solo ese tramo, de la .10 a la .40."],
   ["192.168.1.10", "<b>Una sola dirección.</b> Si escribís esto esperando que recorra la red, no va a encontrar nada."],
   ["mi-nodo.local", "Un nombre de equipo, si tu red los resuelve."]]),
 ("tip", "Si escribís una dirección completa, debajo del campo aparece un botón <b>«Revisar toda 192.168.1.x»</b> que lo corrige de un toque. Para saber cuál es tu red, en Windows abrí <b>cmd</b> y escribí <b>ipconfig</b>: mirá «Dirección IPv4» y usá sus tres primeros números."),
 ("h3", "Leer el resultado"),
 ("p", "Al terminar, el portal dice exactamente qué revisó: <i>«Se revisaron 254 direcciones (192.168.1.1 a 192.168.1.254) en el puerto 80, en 9 s»</i>. Si esa red no es la tuya, lo vas a ver ahí mismo. Los resultados salen en dos grupos:"),
 ("ul", ["<b>Nodos:</b> confirmados. Con <b>Usar</b> cargás la dirección en el formulario.",
         "<b>Otros equipos que respondieron:</b> hay algo en esa dirección pero no se pudo confirmar que sea un nodo, y se explica por qué. El botón <b>Probar</b> te dice el motivo exacto: que no contesta a tiempo, que no deja que el portal le hable, o que es un problema de certificado. <b>Usar igual</b> te permite intentar la conexión de todos modos."]),
 ("p", "El puerto <b>443 (HTTPS)</b> viene desactivado: casi ningún nodo lo usa, obliga a aceptar el certificado a mano y duplica el tiempo de búsqueda. Activalo solo si sabés que tu nodo trabaja con HTTPS."),
 ("warn", "<b>Alcance real de la búsqueda:</b> un navegador no puede abrir conexiones TCP crudas, así que no existe un escaneo de puertos completo. El portal solo detecta nodos que tengan el servidor web (HTTP/HTTPS) activo. Los nodos con certificado HTTPS propio pueden no aparecer hasta que aceptes el certificado visitando antes la dirección en el navegador. Chrome puede pedir permiso para acceder a la red local: aceptalo. <b>En la aplicación de Android esto no pasa</b>: ahí la búsqueda la hace el propio teléfono y prueba los puertos de verdad."),
 ("h3", "Conexiones guardadas y reconexión"),
 ("p", "Cada conexión exitosa se guarda en la pantalla inicial, en <b>Conexiones guardadas</b>. La próxima vez alcanza con tocar <b>Conectar</b> junto a ese nombre, o <b>Reconectar la última</b>. Con <b>Quitar</b> la sacás de la lista."),
 ("tip", "Si el nodo se reinicia (por ejemplo, después de cambiar la región), el portal se reconecta solo cuando el nodo vuelve."),
 ("h3", "Modo demo"),
 ("p", "<b>Ver modo demo (sin nodo)</b> carga un nodo y mensajes de ejemplo para que puedas probar el portal sin equipo. Las capturas de este instructivo están tomadas en modo demo."),
)

ch("Recorrido por la pantalla",
 ("p", "Una vez conectado, la pantalla se divide en tres zonas: la <b>barra superior</b>, el <b>menú lateral</b> y el <b>área de trabajo</b>."),
 ("fig", "03_mensajes", "Pantalla principal (Mensajes)", ["<b>Sonido:</b> activa o apaga el aviso de mensajes nuevos.", "<b>Programar mensaje:</b> abre la ventana de mensajes programados.", "<b>EMERGENCIAS:</b> botón rojo de pánico (también está arriba, en la barra superior).", "<b>Escribí tu mensaje:</b> cuadro para escribir y enviar (hasta 200 caracteres).", "<b>Lista de nodos:</b> tocá un nodo para escribirle un mensaje directo."]),
 ("h3", "Barra superior"),
 ("table", ["Elemento", "Qué indica"], [
   ["Iniciar puente", "Abre el puente de Python y conecta todos los servidores posibles; en verde cuando está activo (capítulo 10)."],
   ["Reloj UTC / Local", "Dos relojes con segundos: la hora UTC (tiempo universal, útil para coordinar con otras estaciones) y la hora local con su diferencia (por ejemplo UTC−03). Salen del reloj de la computadora; al pasar el mouse se ve la fecha completa."],
   ["LoRa", "Estado de la conexión con el nodo: sin nodo, conectado por USB / Bluetooth / Red, o modo demo."],
   ["Internet", "Si la computadora tiene Internet. Sin Internet, la radio funciona igual."],
   ["MQTT", "Cuántos servidores MQTT están conectados (por ejemplo, 2/3), o <i>esperando Internet</i>. Al tocarlo se abre la configuración."],
   ["EMERGENCIAS", "Acceso rápido al botón de pánico."]]),
 ("h3", "Menú lateral"),
 ("ul", ["<b>Navegación:</b> Mensajes, Mapa, Topología, Ajustes y Nodos.",
         "<b>Configuración:</b> radio, dispositivo y módulo del nodo (capítulo 12).",
         "<b>Herramientas:</b> Telemetría, Módulo de consola, Parámetros de emergencia y Novedades y guardia.",
         "<b>Estado del módulo:</b> batería, tensión, uso del canal, versión de firmware y hardware.",
         "<b>Versión del software:</b> firmware y hardware del nodo, y la <b>versión del propio portal</b> con su fecha (por ejemplo <i>Portal: 1.3 · 21/10/2026</i>). Esa línea sirve para confirmar de un vistazo que estás usando el archivo actualizado y no una copia vieja guardada en otra carpeta.",
         "<b>Apariencia:</b> modo claro, oscuro (el que se usa al abrir el portal por primera vez) o alto contraste.",
         "<b>Desconectar:</b> cierra la conexión con el nodo."]),
 ("h3", "Bloques plegables"),
 ("p", "Los títulos <b>Herramientas</b>, <b>Estado del módulo</b>, <b>Versión del software</b> y <b>Apariencia</b> se contraen tocándolos: la flechita cambia de ▾ a ▸. Sirve para pantallas bajas o ventanas chicas, donde si no el listado de navegación queda apretado. El portal se acuerda de cómo los dejaste. La barra lateral completa se desplaza de una sola vez cuando no entra todo."),
)

ch("Mensajes",
 ("p", "La pestaña <b>Mensajes</b> reúne las conversaciones. Arriba aparecen los <b>canales</b> cargados en el nodo (por ejemplo # DEMOmesh y # PRUEBAS); a la derecha, la lista de nodos para mensajes directos. Los mensajes llevan el nombre del nodo que los envió, la hora y, en los tuyos, el estado de envío."),
 ("h3", "Enviar un mensaje"),
 ("steps", [
   "Elegí el canal arriba, o tocá un nodo en la lista de la derecha para un mensaje directo.",
   "Escribí el texto en <b>Escribí tu mensaje…</b> (máximo 200 caracteres; el contador muestra cuánto llevás).",
   "Tocá <b>Enviar</b> o presioná Enter."]),
 ("h3", "Estados y reintentos"),
 ("p", "Si el envío falla, el portal reintenta solo: espera <b>1 minuto</b> y vuelve a enviar; si vuelve a fallar, hace un <b>tercer intento</b> un minuto después. Si tampoco sale, el mensaje queda marcado como <b>NO ENTREGADO</b> y aparece el botón <b>Reenviar mensaje</b> para que el operador lo reenvíe cuando quiera."),
 ("table", ["Marca en el mensaje", "Significado"], [
   ["enviando…", "El mensaje se está entregando al nodo."],
   ["enviado ✓ / entregado ✓", "El nodo confirmó el envío por radio."],
   ["reintento N (cuenta regresiva)", "Falló; el portal volverá a intentar. Podés tocar <b>Reintentar ahora</b>."],
   ["NO ENTREGADO", "Se agotaron los 3 intentos. Tocá <b>Reenviar mensaje</b>."],
   ["MQTT enviando… / en cola", "Si hay servidores MQTT, indica que el mensaje también se publica por Internet o espera a que vuelva la conexión."]]),
 ("h3", "Programar un mensaje"),
 ("p", "Con <b>Programar mensaje</b> el portal envía un texto a la hora que elijas."),
 ("fig", "05_programar", "Ventana Programar mensaje (destinatario: Buscar un nodo)", ["<b>Destinatario:</b> <i>Chat abierto</i> (la conversación en pantalla), <i>Buscar un nodo</i> o <i>Grupo de reenvío</i>.", "<b>Buscador:</b> escribí parte del nombre, la sigla o el ID (!a1b2c3d4) y tocá el nodo de la lista.", "<b>Mensaje:</b> hasta 200 caracteres.", "<b>Fecha y hora:</b> hora de esta PC; tiene que ser futura.", "<b>Programar:</b> deja el mensaje en la lista de programados."]),
 ("fig", "05b_programar_grupo", "Destinatario: Grupo de reenvío", []),
 ("ul", ["<b>Grupo de reenvío:</b> elegí uno de los canales ya cargados o <b>Todos los grupos</b> para que el mismo texto salga por cada canal.",
         "En la lista <b>Programados</b> ves cada envío con su estado: <i>esperando la hora</i>, <i>enviado</i> o <i>vencido</i>. Podés cancelarlos o, si vencieron, tocar <b>Enviar ahora</b>."]),
 ("warn", "<b>El portal debe estar abierto y conectado al nodo a la hora programada.</b> Si el nodo no está conectado, el portal espera hasta 15 minutos; pasado ese tiempo el mensaje queda como <i>vencido</i>."),
 ("h3", "Imprimir o guardar los chats"),
 ("p", "<b>Imprimir / PDF</b> arma un informe con los mensajes y todos sus datos (hora, remitente, señal, saltos) listo para imprimir o guardar como PDF desde el navegador."),
)

ch("Botón de EMERGENCIAS",
 ("p", "El botón rojo <b>EMERGENCIAS</b> (en el menú lateral y en la barra superior) abre una ventana para enviar <b>la misma alerta a todos los canales activos</b>, uno detrás del otro. No se usa para mensajes directos."),
 ("fig", "04_panico", "Ventana de emergencias con todos los datos opcionales", ["<b>Mensaje:</b> texto de la alerta.", "<b>Teléfono (opcional):</b> número para que te llamen.", "<b>País de emergencia (opcional):</b> escribilo o elegí uno de la lista.", "<b>Frecuencia de radio (opcional):</b> activá el interruptor, elegí VHF o UHF y escribí los MHz.", "<b>Enviar mi coordenada:</b> agrega la posición del nodo, si la tiene.", "<b>Se enviará así:</b> vista previa del texto final y los bytes usados.", "<b>Enviar alerta a todos los canales.</b>"]),
 ("h3", "Cómo enviar una alerta"),
 ("steps", [
   "Tocá <b>EMERGENCIAS</b>.",
   "Revisá o escribí el mensaje. Completá, si querés, teléfono, país y frecuencia, y decidí si se envía tu coordenada.",
   "Mirá la vista previa <b>Se enviará así</b>: el total no puede pasar los <b>200 bytes</b> (los acentos ocupan más de un byte).",
   "Tocá <b>ENVIAR ALERTA A TODOS LOS CANALES</b>. Se envía por cada canal con una pequeña pausa y el portal te lleva a la conversación."]),
 ("ul", ["La frecuencia se valida: <b>VHF</b> entre 30 y 300 MHz y <b>UHF</b> entre 300 y 3000 MHz.",
         "Si el nodo todavía no informó su posición, no se puede agregar la coordenada.",
         "Si el nodo no está conectado, el envío falla y se reintenta; después aparece <b>Reenviar mensaje</b>."]),
 ("h3", "Parámetros de emergencia (Herramientas)"),
 ("p", "En <b>Herramientas → Parámetros de emergencia</b> dejás guardados los valores con los que se abre el cuadro de alerta, así en una emergencia sólo hay que tocar enviar."),
 ("fig", "10_emergencia", "Herramienta Parámetros de emergencia", ["<b>Teléfono</b> predeterminado.", "<b>País de emergencia</b> predeterminado.", "<b>Frecuencia de radio:</b> interruptor, banda VHF/UHF y MHz.", "<b>Enviar mi coordenada:</b> sí / no.", "<b>Vista previa</b> del mensaje final.", "<b>Guardar</b>, <b>Restaurar</b> los valores de fábrica o <b>Abrir el cuadro de alerta</b>."]),
 ("tip", "Cargá los parámetros <b>antes</b> de salir a terreno y probá una alerta con un compañero para confirmar que llega."),
)

ch("Nodos y favoritos",
 ("p", "<b>Nodos</b> muestra todos los nodos que el equipo conoce, con modelo, última vez que se escuchó, SNR (calidad de señal), tipo de conexión, batería y distancia."),
 ("fig", "06_nodos", "Lista de nodos con filtros", ["<b>Alcance:</b> Todos, <i>Solo directos</i> (sin saltos intermedios) o <i>Solo por MQTT</i>.", "<b>Estado:</b> Todos, <i>Conectados</i> o <i>Desconectados</i>. Un nodo se considera desconectado si hace más de 2 horas que no se escucha; ese tiempo se puede cambiar (15 min, 1, 2, 6 o 24 horas).", "<b>Favoritos:</b> Todos o <i>Solo favoritos</i>.", "<b>Función del nodo:</b> Cliente, Nodo, Nodo cliente, Repetidor y Otros; se pueden marcar varios.", "<b>Estrella:</b> marca o quita un favorito.", "<b>Acciones:</b> Mensaje, Ruta, Posición y Quitar."]),
 ("h3", "Filtros"),
 ("p", "Los filtros se combinan entre sí; por ejemplo, <i>Solo directos</i> + <i>Desconectados</i> + <i>Repetidor</i>. El título muestra cuántos nodos pasan el filtro (por ejemplo, <b>Nodos (3 de 5)</b>) y <b>Limpiar filtros</b> los reinicia. Tu propio nodo siempre queda en la lista. Los filtros se recuerdan la próxima vez que abras el portal."),
 ("table", ["Función", "Roles de la red que incluye"], [
   ["Cliente", "Cliente, cliente silencioso, cliente oculto y cliente base."],
   ["Nodo", "Router y router tardío (reenvían el tráfico de la malla)."],
   ["Nodo cliente", "Router + cliente (rol heredado)."],
   ["Repetidor", "Repetidor puro."],
   ["Otros", "Rastreador, sensor, TAK, objetos perdidos o rol desconocido."]]),
 ("h3", "Favoritos"),
 ("ul", ["Tocá la <b>☆</b> junto al nodo para marcarlo como favorito (<b>★</b>). Tocala de nuevo para quitarlo.",
         "Los favoritos aparecen <b>primero</b> en la lista de Nodos y en la lista de Mensajes, con un anillo dorado en el mapa.",
         "Se guardan en el navegador y, si hay un nodo conectado, también se le avisa para que los guarde en su propia lista.",
         "En <b>Sonidos y notificaciones</b> podés darles un tono propio."]),
 ("h3", "Acciones sobre un nodo"),
 ("ul", ["<b>Mensaje:</b> abre un mensaje directo.", "<b>Ruta:</b> envía un <i>traceroute</i> para ver por qué nodos pasa el camino.", "<b>Posición:</b> le pide al nodo que informe su posición.", "<b>Quitar:</b> lo borra de la lista del equipo (pide confirmación).", "<b>Exportar CSV:</b> descarga la lista; si hay filtros activos, solo exporta los nodos filtrados."]),
)

ch("Mapa",
 ("p", "El <b>Mapa</b> muestra tu nodo y los nodos que informaron su posición. Podés arrastrar para moverte y usar la rueda del mouse (o pellizcar) para acercar. <b>Ajustar a los nodos</b> encuadra todos."),
 ("fig", "07_mapa", "Mapa con un nodo seleccionado", ["<b>Cuadro del nodo:</b> aparece al tocar un nodo.", "<b>Estrella:</b> favorito.", "<b>Altura s. n. m.:</b> altura sobre el nivel del mar que informa el nodo.", "<b>Saltos:</b> <i>Directo (0 saltos)</i>, la cantidad de saltos, o <i>vía MQTT</i>."]),
 ("ul", ["El cuadro del nodo también muestra posición, distancia y rumbo desde tu nodo, última vez visto, SNR, batería y temperatura.",
         "<b>Cómo llegar</b> abre Google Maps con la ruta; <b>Copiar coordenadas</b> copia la posición; <b>Mensaje directo</b> y <b>Ver telemetría</b> saltan a esas pantallas.",
         "Si el nodo informa altura 0, el cuadro muestra <i>sin dato</i>: muchos equipos envían 0 cuando no tienen la altura.",
         "El panel <b>Capas</b> activa o apaga etiquetas, enlaces directos (coloreados por SNR), vecinos, rastros de movimiento, cobertura medida, waypoints, cuadrícula, anillos de distancia y mapas base (calles, topográfico, satélite, IGN Argentina, etc.)."]),
 ("note", "El color del borde de cada nodo es el <b>semáforo</b> (verde, amarillo, rojo intermitente o gris). Se explica en el capítulo 14.") ,
 ("note", "Los mapas base necesitan Internet. Sin Internet se ven los nodos y las capas propias sobre fondo liso, y los mapas ya visitados se guardan para uso sin conexión."),
)

ch("Internet y MQTT",
 ("p", "Cuando hay Internet, el portal puede conectarse a servidores <b>MQTT</b> para publicar tus mensajes de canal y recibir los de otros nodos. Se configura en <b>Ajustes → Internet y MQTT</b>, donde se ve el estado actual (Internet, nodo, servidores, mensajes enviados y recibidos, cola)."),
 ("fig", "08_mqtt", "Ajustes → Internet y MQTT", []),
 ("h3", "Cómo se envían tus mensajes (importante)"),
 ("p", "Cuando enviás un mensaje de canal, el portal lo publica por <b>el primer servidor que esté conectado</b>. Si ese servidor falla justo en ese momento, pasa automáticamente al siguiente de la lista. <b>No</b> publica la misma copia en todos los servidores: con que salga por uno, alcanza. En cada mensaje enviado vas a ver entre paréntesis por qué servidor salió."),
 ("table", ["Opción (en «General»)", "Qué hace"], [
   ["Usar MQTT", "Interruptor general. Cada servidor tiene además su propio encendido."],
   ["Enviar mis mensajes también por MQTT", "Publica tus mensajes de canal por el primer servidor conectado (con reserva automática al siguiente si falla). Si no hay ninguno, quedan en cola hasta 1 hora."],
   ["Enviar por todos los servidores a la vez", "Opción avanzada, apagada por defecto. Solo si la encendés, el portal publica la misma copia en cada servidor conectado (redundante)."],
   ["Recibir mensajes y nodos por MQTT", "Muestra lo que llega de tus canales. Si el mismo mensaje llega por varios servidores, se muestra una sola vez."]]),
 ("note", "<b>No es obligatorio que todos los servidores funcionen.</b> Podés dejar encendido <b>uno solo</b>, algunos o todos. Los que estén apagados o sin conexión no afectan a los demás: mientras haya al menos uno conectado, tus mensajes salen."),
 ("h3", "Servidores"),
 ("p", "Hay <b>seis lugares de servidor</b>, que se pueden encender y apagar por separado con el interruptor <b>Usar este servidor</b>. El N.º 1 es el servidor oficial de la red, ya cargado con sus datos públicos. Los otros traen cargados servidores públicos de prueba (HiveMQ, EMQX, Mosquitto, Eclipse IoT y Flespi); también podés escribir los tuyos. Para usar uno solo, dejá encendido ese y apagá el resto."),
 ("fig", "08b_mqtt_servidores", "Datos de un servidor", ["<b>Número de servidor</b> y estado (conectado, esperando Internet, error)."]),
 ("table", ["Campo", "Para qué sirve"], [
   ["Usar este servidor", "Enciende o apaga ese servidor."],
   ["Dirección y Puerto TCP", "Datos del servidor (8883 con TLS, 1883 sin cifrar)."],
   ["TLS (seguro)", "Conexión cifrada."],
   ["Dirección web (WebSocket)", "Dirección ws:// o wss:// del servidor. Si la dejás vacía, el portal busca sola una dirección válida."],
   ["Usuario / Contraseña", "Credenciales del servidor (se guardan solo en este navegador)."],
   ["Tema raíz", "Prefijo de los temas MQTT (por ejemplo msh/ANZ); si lo dejás vacío se usa el de la región del nodo."]]),
 ("h3", "¿Por qué hace falta el puente?"),
 ("p", "Los navegadores solo pueden hablar con servidores MQTT que ofrezcan <b>WebSocket</b>. Si un servidor solo ofrece MQTT por TCP (como suele pasar con el oficial), tenés dos opciones: usar el <b>puente local</b> o tocar <b>Aplicar al nodo</b> para que el propio nodo se conecte por su WiFi o Ethernet. El paso a paso del puente está en el capítulo siguiente."),
 ("h3", "Usar el puente local (Windows)"),
 ("steps", [
   "Instalá <b>Python 3</b> desde python.org y, durante la instalación, marcá <b>Add Python to PATH</b>.",
   "Copiá <b>puente-mqtt.py</b> e <b>iniciar-puente.bat</b> a la <b>misma carpeta</b>.",
   "Hacé doble clic en <b>iniciar-puente.bat</b>. Se abre una ventana negra que dice <i>Puente MQTT listo</i> y lista los servidores que atiende.",
   "<b>Dejá esa ventana abierta</b> mientras usás el portal. El portal detecta el puente solo, sin configurar nada. Para cerrarlo, presioná Ctrl+C o cerrá la ventana."]),
 ("ul", ["Una sola ventana del puente alcanza para <b>todos</b> los servidores que uses; no hace falta una por servidor.",
         "<b>python puente-mqtt.py --probar</b> prueba cada servidor (conexión y saludo MQTT) e indica cuáles responden.",
         "<b>python puente-mqtt.py --permitir mi.servidor.com</b> permite además otro servidor propio.",
         "Por seguridad, el puente solo escucha en tu propia computadora y solo reenvía a los servidores de su lista y a los puertos MQTT habituales."]),
 ("h3", "Aplicar al nodo"),
 ("p", "<b>Aplicar al nodo</b> escribe en el módulo MQTT del propio nodo los datos del servidor; el nodo se reinicia y se conecta solo por su WiFi o Ethernet. Es útil cuando no querés dejar la computadora encendida."),
 ("warn", "Los servidores públicos son compartidos y no son privados: no los uses para información sensible. Lo que se publica en un servidor público puede ser leído por otras personas."),
)

ch("Ejecutar el puente para todos los servidores",
 ("p", "El <b>puente</b> es un pequeño programa de Python que se ejecuta en tu computadora y permite que el portal use servidores MQTT que no ofrecen WebSocket. <b>Una sola ventana del puente atiende a todos los servidores a la vez</b>: el servidor oficial de la red (N.º 1) y los cinco servidores públicos (HiveMQ, EMQX, Mosquitto, Eclipse IoT y Flespi), es decir, los seis lugares del portal. No hace falta abrir un puente por servidor."),
 ("h3", "El botón “Iniciar puente” (la forma más fácil)"),
 ("p", "En la barra superior hay un botón <b>Iniciar puente</b>. Al tocarlo, el portal abre el puente de Python sin ventana y <b>enciende todos los servidores posibles</b> (todos los que tienen dirección y no necesitan un token que falte, como Flespi). Cuando el puente responde, el botón se pone verde y dice <b>Puente: activo</b>."),
 ("warn", "<b>Instalación de una sola vez (Windows).</b> Una página web no puede ejecutar programas por sí sola, así que el botón usa un enlace propio que se registra una vez: 1) dejá en una misma carpeta <b>puente-mqtt.py</b>, <b>lanzar-puente.vbs</b> e <b>instalar-boton-puente.bat</b>; 2) hacé doble clic en <b>instalar-boton-puente.bat</b> (no pide permisos de administrador); 3) tocá <b>Iniciar puente</b> en el portal y, cuando el navegador pregunte si abre “Puente OPEN SOURCE PARIZ”, tocá <b>Abrir</b>. No muevas la carpeta después; si la movés, ejecutá el instalador otra vez."),
 ("ul", ["<b>detener-puente.bat</b> cierra el puente que se abrió sin ventana.", "<b>desinstalar-boton-puente.bat</b> quita el enlace del registro de Windows.", "Si no instalás nada, sigue valiendo <b>iniciar-puente.bat</b> (con ventana): el botón del portal se pone verde solo al detectarlo.", "El enlace solo arranca el puente: no acepta órdenes ni datos de las páginas web."]),
 ("h3", "Qué servidores atiende"),
 ("table", ["N.º", "Servidor", "Puertos que atiende el puente", "Notas"], [
   ["1", "Servidor oficial de la red", "8883 (TLS), 1883", "Viene encendido y con sus datos públicos cargados."],
   ["2", "HiveMQ (público)", "1883, 8883", "Viene encendido."],
   ["3", "EMQX (público)", "1883, 8883", "Viene encendido."],
   ["4", "Mosquitto (público)", "8886 (TLS), 8883, 1883, 8884", "Viene apagado; se enciende en el portal."],
   ["5", "Eclipse IoT (público)", "1883, 8883", "Viene apagado; se enciende en el portal."],
   ["6", "Flespi", "8883, 1883", "Viene apagado; pide un token propio (ver más abajo)."]]),
 ("note", "Si un servidor ofrece WebSocket, el portal se conecta directamente y no necesita el puente. El puente se usa solamente cuando el servidor no responde por WebSocket; el portal lo detecta solo."),
 ("warn", "<b>Seguridad.</b> El puente solo escucha en tu computadora (127.0.0.1) y solo reenvía a los servidores de su lista: no lo expongas a la red. Los servidores públicos no son privados: no publiques información sensible."),
 ("h3", "Antes de empezar"),
 ("ul", ["Una computadora con <b>Windows 10 u 11</b> (también sirve en macOS y Linux) con Internet.",
         "<b>Python 3.8 o más nuevo</b>. Descargalo desde python.org y, en la primera pantalla del instalador, marcá <b>Add Python to PATH</b> antes de tocar Install Now.",
         "Los archivos <b>puente-mqtt.py</b> e <b>iniciar-puente.bat</b> en <b>la misma carpeta</b> (por ejemplo, C:\\PuenteMQTT)."]),
 ("h3", "Paso 1: comprobar que Python está instalado"),
 ("steps", [
   "Abrí la carpeta donde guardaste los archivos del puente.",
   "Hacé clic en la <b>barra de direcciones</b> del Explorador de archivos, escribí <b>cmd</b> y presioná Enter. Se abre una ventana negra ya ubicada en esa carpeta.",
   "Escribí <b>python --version</b> y presioná Enter. Tiene que responder algo como <i>Python 3.12.x</i>. Si dice que no encuentra el comando, probá con <b>py -3 --version</b>; si tampoco, reinstalá Python marcando <i>Add Python to PATH</i>."]),
 ("h3", "Paso 2: iniciar el puente para todos los servidores"),
 ("p", "Hay dos formas, las dos hacen lo mismo:"),
 ("ul", ["<b>Con doble clic:</b> abrí <b>iniciar-puente.bat</b>.",
         "<b>Desde la ventana negra:</b> escribí <b>python puente-mqtt.py</b> y presioná Enter (si usás el lanzador de Python: <b>py -3 puente-mqtt.py</b>)."]),
 ("p", "No hace falta agregar nada más: sin parámetros, el puente atiende a <b>todos</b> los servidores de la lista. Tiene que aparecer una ventana como esta:"),
 ("fig", "17_terminal", "Ventana del puente funcionando para todos los servidores", ["<b>Puente MQTT listo en ws://localhost:9001:</b> el puente está escuchando en tu computadora.", "<b>Lista de servidores:</b> los seis servidores que atiende y los puertos permitidos.", "<b>Dejá esta ventana abierta.</b> Mientras esté abierta, el puente funciona."]),
 ("warn", "<b>No cierres la ventana negra</b> mientras uses el portal: si la cerrás, el puente se detiene y los servidores que dependen de él se desconectan. Para detenerlo a propósito, presioná <b>Ctrl+C</b> o cerrá la ventana."),
 ("h3", "Paso 3: comprobar que el puente responde"),
 ("steps", [
   "Con el puente en marcha, abrí en el navegador la dirección <b>http://localhost:9001</b>.",
   "Tiene que aparecer el texto <b>Puente MQTT funcionando</b>. Si ves un error de conexión, el puente no está iniciado."]),
 ("h3", "Paso 4: encender los seis servidores en el portal"),
 ("steps", [
   "Abrí el portal y entrá en <b>Ajustes → Internet y MQTT</b>.",
   "Bajá hasta los seis cuadros de servidor y activá <b>Usar este servidor</b> en cada uno que quieras usar (el N.º 1, el 2 y el 3 vienen encendidos).",
   "Para el <b>N.º 6 (Flespi)</b>: creá una cuenta gratuita en flespi.io, copiá tu token y en <b>Usuario</b> escribí <b>FlespiToken </b> (con un espacio) seguido de tu token; la contraseña queda vacía. Sin token no conecta.",
   "Mirá la barra superior: el indicador <b>MQTT</b> pasa a mostrar cuántos servidores están conectados (por ejemplo, <b>MQTT: 5/6 conectados</b>). Cada cuadro de servidor muestra su propio estado."]),
 ("fig", "18_seis_servidores", "Los seis lugares de servidor en Ajustes → Internet y MQTT (recorte de cada cabecera)", []),
 ("p", "El portal prueba cada servidor primero por una dirección web (WebSocket) y, si no responde, pasa automáticamente al puente. No hay que escribir la dirección del puente en ningún lado."),
 ("h3", "Paso 5 (opcional): probar los servidores desde el puente"),
 ("p", "El puente trae una prueba que verifica, uno por uno, si cada servidor responde. Detené el puente (Ctrl+C), y en la ventana negra escribí:"),
 ("code", "python puente-mqtt.py --probar"),
 ("p", "Muestra una línea por servidor con el puerto, si usa TLS, el tiempo de respuesta y el resultado del saludo MQTT, y al final cuántos de los seis respondieron. <i>Usuario o clave incorrectos</i> también indica que el servidor está vivo: lo único que falta es cargar las credenciales en el portal."),
 ("h3", "Otras formas de ejecutarlo"),
 ("table", ["Qué querés hacer", "Comando"], [
   ["Atender a todos los servidores (lo normal)", "python puente-mqtt.py"],
   ["Probar los servidores y salir", "python puente-mqtt.py --probar"],
   ["Permitir además un servidor propio", "python puente-mqtt.py --permitir mi.servidor.com"],
   ["Cambiar el puerto local (no recomendado: el portal busca el 9001)", "python puente-mqtt.py --escuchar 9002"],
   ["En macOS o Linux", "python3 puente-mqtt.py"],
   ["Modo viejo: un solo servidor", "python puente-mqtt.py servidor.com 1883"]]),
 ("h3", "Que arranque junto con Windows (opcional)"),
 ("steps", [
   "Hacé clic derecho sobre <b>iniciar-puente.bat</b> → <i>Crear acceso directo</i>.",
   "Presioná las teclas <b>Windows + R</b>, escribí <b>shell:startup</b> y presioná Enter: se abre la carpeta de inicio.",
   "Copiá el acceso directo dentro de esa carpeta. La próxima vez que enciendas la computadora, el puente se abre solo."]),
 ("h3", "Si algo no funciona"),
 ("table", ["Síntoma", "Qué probar"], [
   ["Se cierra la ventana al instante.", "Python no está instalado o no está en el PATH. Repetí el paso 1 y reinstalá Python marcando <i>Add Python to PATH</i>."],
   ["Dice que el puerto 9001 ya está en uso.", "Ya hay un puente abierto. Cerrá la otra ventana o usá <b>--escuchar</b> con otro puerto."],
   ["El navegador no abre http://localhost:9001.", "El puente no está iniciado o un firewall lo bloquea. Permití Python en el Firewall de Windows (solo redes privadas)."],
   ["Un servidor sigue en rojo.", "Ejecutá <b>--probar</b>. Si no responde, el servidor puede estar caído o tu red bloquea esos puertos (8883, 1883, 8886). Probá desde otra red."],
   ["En la ventana aparece <i>rechazado (no está en la lista)</i>.", "El portal pidió un servidor que no está permitido. Agregalo con <b>--permitir</b>."],
   ["Flespi no conecta.", "Falta el token o está mal escrito: Usuario = <b>FlespiToken </b> + token, contraseña vacía."]]),
)

ch("Sonidos y notificaciones",
 ("p", "Cada tipo de aviso tiene su propio tono. Se configuran en <b>Ajustes → Sonidos y notificaciones</b>."),
 ("fig", "09_sonidos", "Ajustes → Sonidos y notificaciones", ["<b>Tono:</b> elegí uno de la lista (Alerta, Suave, Campana, Beep de radio, Gota, Ascendente, Descendente, Sirena, Urgente).", "<b>▶ Probar:</b> lo escuchás en el momento.", "<b>Mi sonido…:</b> cargá un archivo de audio propio (corto, hasta 400 KB)."]),
 ("h3", "Qué se puede configurar"),
 ("table", ["Opción", "Descripción"], [
   ["Sonidos activados / Volumen", "Interruptor general y volumen de todos los tonos."],
   ["Silencio nocturno", "No suena nada entre las horas que elijas (por ejemplo de 22:00 a 07:00). El botón Probar siempre suena."],
   ["Mensaje directo", "Tono cuando te escribe un nodo. Por defecto: <i>Alerta</i> (4 notas agudas)."],
   ["Mensaje de un canal", "Tono cuando llega un mensaje a un grupo. Por defecto: <i>Suave</i> (2 notas graves)."],
   ["Mensaje de un nodo favorito", "Si el mensaje es de un favorito, suena este tono en lugar de los anteriores."],
   ["Mensaje entregado / no entregado", "Aviso cuando el nodo confirma el envío o cuando se agotan los reintentos."],
   ["Conexión con el nodo", "Aviso al conectarse o al perder la conexión."],
   ["Canales", "Silenciá los grupos que hablan mucho; los directos y los favoritos siguen sonando."]]),
 ("tip", "El botón <b>🔔 Sonido: sí / 🔕 Sonido: no</b> de la pestaña Mensajes es un acceso rápido al interruptor general."),
 ("note", "Los navegadores solo reproducen sonido después de que hiciste algún clic en la página; si no escuchás nada al abrir el portal, tocá cualquier lugar de la pantalla una vez."),
)

ch("Configuración del nodo",
 ("p", "En el menú lateral, <b>Configuración</b> reúne los ajustes del propio equipo: <b>radio</b>, <b>dispositivo</b> y <b>módulo</b>. Cada pantalla tiene un botón <b>Guardar</b> que envía los cambios al nodo."),
 ("fig", "11_radio", "Configuración de radio → LoRa", []),
 ("h3", "Radio"),
 ("ul", ["<b>LoRa:</b> preset de módem, <b>región</b> (debe coincidir con tu país; en Argentina corresponde ANZ / 915 MHz), límite de saltos, potencia de transmisión y más.",
         "<b>Canales:</b> hasta 8 canales; el 0 es el primario. Cada uno tiene nombre, clave (PSK) y opciones de subir/bajar a MQTT. Se pueden compartir e importar por enlace.",
         "<b>Seguridad:</b> claves del nodo y administración."]),
 ("fig", "12_canales", "Configuración de radio → Canales", []),
 ("h3", "Dispositivo y módulo"),
 ("ul", ["<b>Dispositivo:</b> usuario (nombre largo y corto), rol del nodo, posición, consumo, red WiFi, pantalla y Bluetooth.",
         "<b>Módulo:</b> MQTT del nodo, conexión serial, notificación externa, Store &amp; Forward, test de alcance, telemetría, mensajes predefinidos y otros."]),
 ("warn", "<b>Cuidado con la región y el preset.</b> Cambiarlos reinicia el nodo y, si no coinciden con los de los demás nodos de tu red, <b>dejás de verlos</b>. Un nodo sin región configurada no transmite. Antes de cambiar la configuración, hacé un respaldo (capítulo 14)."),
)

ch("Herramientas: telemetría y consola",
 ("h3", "Telemetría"),
 ("p", "Muestra lo que reporta el nodo y los demás nodos de la malla: batería, tensión, uso del canal, aire TX, temperatura, humedad, presión, tiempo encendido y más, con historial. Hay una vista <b>Todos los nodos</b> y una de <b>Detalle por nodo</b>. Podés exportar a CSV o a JSON."),
 ("fig", "13_telemetria", "Telemetría de todos los nodos", []),
 ("note", "<b>Muchos registros sin trabarse.</b> Las tablas de nodos, de telemetría y de guardia y la lista de mensajes dibujan solamente las filas que se ven en pantalla. Por eso se pueden acumular miles de registros sin que el navegador se ponga lento; al desplazarte, las filas se van armando en el momento. Los mensajes guardados en el navegador se limitan a los más recientes (hasta 4000)."),
 ("h3", "Módulo de consola"),
 ("p", "La consola muestra el <b>tráfico de radio</b> que pasa por el nodo: hora, origen, destino, tipo de paquete, SNR y RSSI. Sirve para diagnosticar. Podés <b>Pausar</b> la lista y <b>Limpiar</b> el historial."),
 ("fig", "14_consola", "Tráfico de radio", []),
)

ch("Semáforo, alertas y modo operativo",
 ("p", "Cada nodo tiene un color que resume su estado. Aparece en el borde del nodo en el mapa, en la lista de nodos, en la telemetría y en la topología, siempre con el mismo significado."),
 ("table", ["Color", "Significado"], [
   ["<b>Verde</b>", "Activo: se lo escuchó dentro del tiempo límite y con batería y señal normales."],
   ["<b>Amarillo</b>", "En atención: batería baja o señal débil (SNR bajo). El nodo sigue activo."],
   ["<b>Rojo intermitente</b>", "Alerta de pánico recibida y sin atender, o nodo caído (no se lo escucha hace más de lo permitido)."],
   ["<b>Gris</b>", "Todavía sin datos suficientes."]]),
 ("fig", "19_semaforo", "Mapa con el semáforo y la barra de alertas", ["<b>Barra de alertas:</b> aparece arriba de todo cuando llega una alerta de pánico. Tiene tres botones: <i>Ver en el mapa</i>, <i>Ver mensaje</i> y <i>Marcar atendida</i>.", "<b>Contadores:</b> cuántos nodos hay en cada estado (activos, en atención, caídos y alertas).", "<b>Marcar atendida:</b> apaga el parpadeo y la barra de esa alerta y deja constancia en el registro."]),
 ("p", "Una alerta de pánico es un mensaje que empieza con 🚨, ⚠, SOS, EMERGENCIA, PÁNICO o ALERTA (el botón de EMERGENCIAS de este portal arma el mensaje así). Al llegar suena el tono <b>urgente</b>, parpadea el nodo y queda anotada en el registro de eventos. También se registran cuando un nodo se cae o vuelve, cuando tiene la batería baja o la señal débil, y cuando se envía una alerta propia."),
 ("h3", "Modo operativo: apariencia y umbrales"),
 ("p", "Desde <b>Ajustes → Modo operativo y semáforo</b> elegís el tema de colores y los límites del semáforo. El portal se abre con el <b>tema oscuro</b>: cansa menos la vista de noche o con poca luz."),
 ("fig", "20_modo_operativo", "Ajustes del modo operativo", []),
 ("ul", ["<b>Oscuro (táctico):</b> fondo oscuro, el predeterminado.",
         "<b>Alto contraste:</b> negro puro con texto blanco y bordes marcados, para máxima legibilidad.",
         "<b>Nocturno rojo:</b> tonos rojos que conservan la visión nocturna (incluye el mapa).",
         "<b>Claro:</b> para uso a pleno sol o para imprimir pantallas.",
         "<b>Umbrales:</b> minutos sin señal para considerar caído a un nodo (120 por defecto), porcentaje de batería baja (20 %) y SNR considerado débil (−10 dB). También se puede ocultar la barra de alertas."]),
 ("note", "El tema también se cambia desde el menú lateral (<i>Apariencia</i>). Los umbrales se guardan en este navegador."),
)

ch("Topología de la red",
 ("p", "La solapa <b>Topología</b> dibuja la red como un diagrama: tu nodo en el centro, los nodos que escuchás directamente en el primer anillo y los que llegan a través de repetidores en los anillos siguientes. Muestra <b>qué se midió</b> y <b>qué se dedujo</b>, y los mantiene claramente separados."),
 ("warn", "<b>Regla de este diagrama:</b> una línea <b>continua</b> significa que hay una medición real de ese tramo. Una línea <b>punteada</b> es solo una inferencia: <u>no afirma</u> que exista una conexión directa entre los dos nodos. La distancia dibujada no es la distancia real."),
 ("h3", "Tipos de enlace"),
 ("table", ["Línea", "Qué es", "Cómo se sabe"], [
   ["<b>Continua de color (según SNR)</b>", "Enlace directo observado", "Tu nodo recibió paquetes de ese nodo sin ningún repetidor en el medio (saltos = 0)."],
   ["<b>Continua azul</b>", "Informado por un vecino", "Otro nodo declaró en su tabla de vecinos (NeighborInfo) que escucha al otro. Lo midió él, no tu nodo."],
   ["<b>Continua violeta</b>", "Medido con traceroute", "Un traceroute pasó realmente por ese tramo y cada nodo anotó el SNR con que lo recibió."],
   ["<b>Punteada naranja</b>", "Inferido, no confirmado", "No hay medición. Se deduce de los saltos del paquete y del último byte del ID del repetidor, que puede coincidir con otro nodo."]]),
 ("fig", "21_topologia_inferido", "Topología con un enlace inferido seleccionado", ["<b>Filtros:</b> permiten mostrar u ocultar cada tipo de enlace y elegir cuánto tiempo hacia atrás se toman las mediciones (1 hora a 7 días).", "<b>Resumen:</b> cuántos nodos son directos, cuántos dependen de repetidores, cuántos llegan solo por Internet y cuántos enlaces están observados o inferidos.", "<b>Leyenda:</b> recuerda el significado de cada línea y de las formas de los nodos (círculo: directo; cuadrado: con repetidores).", "<b>Etiqueta de estado:</b> indica sin vueltas si el enlace está confirmado o <i>solo inferido</i>.", "<b>Detalle de la medición:</b> RSSI, SNR, saltos y antigüedad. Cuando no hay dato, dice <i>no informado</i> en lugar de inventarlo.", "<b>Advertencia:</b> explica por qué la inferencia puede ser incorrecta."]),
 ("h3", "Qué muestra cada enlace"),
 ("p", "Al tocar un enlace, el panel de la derecha lista <b>todas</b> las evidencias que hay de ese tramo, de la más firme a la más débil. Para cada una informa:"),
 ("ul", ["<b>RSSI</b> (potencia recibida, en dBm) y <b>SNR</b> (relación señal-ruido, en dB), cuando el método los provee. El traceroute y las tablas de vecinos solo informan SNR.",
         "<b>Saltos:</b> 0 en un enlace directo; en un traceroute, un tramo y el largo total de la ruta; en una inferencia, los saltos totales hasta el nodo.",
         "<b>Antigüedad de la medición:</b> hace cuánto se midió y la fecha y hora exactas. Las líneas con más de 6 horas se dibujan más tenues.",
         "<b>Medido por:</b> qué nodo hizo la medición."]),
 ("fig", "22_topologia_observado", "Enlace con varias evidencias", ["<b>Confirmado:</b> hay al menos una medición propia o ajena.", "<b>Enlace directo observado:</b> medición de tu nodo, con RSSI y SNR.", "<b>Informado por un vecino:</b> medición de otro nodo; no trae RSSI."]),
 ("h3", "Qué muestra cada nodo"),
 ("ul", ["La clase del nodo: <i>se escucha directamente</i>, <i>llega a través de repetidores</i> (con la cantidad de saltos), <i>aparece solo en la tabla de vecinos de otro nodo</i>, <i>llega solo por Internet (MQTT)</i> o <i>sin datos suficientes</i>.",
         "Los nodos que llegan solo por MQTT y los que no tienen datos se dibujan <b>aparte</b>, en bandas debajo del diagrama y sin líneas, porque no hay enlace de radio que mostrar.",
         "El SNR y el RSSI de un nodo que llega con saltos describen <b>el último tramo</b> (desde el repetidor hasta tu nodo), no el enlace con ese nodo. El panel lo aclara.",
         "Los botones <b>Trazar ruta</b> (traceroute) y <b>Ver en el mapa</b>. Al recibir la respuesta del traceroute, los tramos intermedios pasan de <i>inferidos</i> a <i>observados</i>."]),
 ("tip", "Para mover el diagrama, arrastralo; para acercar, usá la rueda del mouse, el pellizco o los botones ＋ y －. <b>Ajustar vista</b> vuelve a encuadrar todo."),
 ("note", "Cuanto más tiempo lleve el portal abierto y conectado, más enlaces se observan. Las mediciones se guardan en el navegador (los traceroutes, hasta los últimos 60)."),
)

ch("Novedades y Libro de Guardia",
 ("p", "Este módulo reúne los mensajes y los eventos del sistema en una sola lista, la filtra por rango de horas y la exporta para completar el libro de guardia, las actas y los informes de novedades."),
 ("fig", "23_guardia", "Novedades y Libro de Guardia", ["<b>Rango de horas:</b> últimas 8, 12 o 24 horas, hoy, ayer, o un período <i>personalizado</i> con <i>Desde</i> y <i>Hasta</i>.", "<b>Qué incluir:</b> mensajes de canales, mensajes directos, alertas de pánico, nodos caídos o recuperados, batería baja o señal débil, y conexión del nodo local.", "<b>Solo eventos críticos:</b> deja únicamente alertas de pánico, nodos caídos y batería baja o señal débil.", "<b>Buscar:</b> por texto, nodo o canal; también hay un selector de nodo.", "<b>Contador:</b> cantidad de registros y de críticos del período elegido.", "<b>Exportar:</b> <i>CSV</i>, <i>Excel (.xlsx)</i> y <i>PDF / Imprimir</i>."]),
 ("h3", "Armar el acta paso a paso"),
 ("steps", [
   "Elegí el <b>rango de horas</b> de la guardia (por ejemplo, desde las 20:00 hasta las 08:00 con <i>Personalizado</i>).",
   "Marcá qué tipos de registro querés incluir o activá <b>Solo eventos críticos</b>.",
   "Completá <b>Datos del acta</b>: dependencia, jefe de guardia u operador y observaciones. Esos datos salen en el encabezado del PDF y de la hoja de Excel.",
   "Exportá. En <b>Excel</b> se genera un libro con la hoja <i>Novedades</i> (fechas reales, filtros y primera fila fija) y la hoja <i>Resumen</i>. El <b>PDF</b> abre la ventana de impresión: elegí <i>Guardar como PDF</i>."]),
 ("ul", ["Cada registro muestra la hora local y la hora UTC, el tipo, el nodo, el canal o destino y el detalle. Los críticos se resaltan en rojo.",
         "Una alerta de pánico recibida aparece una sola vez, aunque tenga un mensaje y un evento asociados.",
         "El período, los filtros y los datos del acta quedan guardados en este navegador."]),
 ("note", "La lista solo incluye lo que este navegador recibió y guardó: los mensajes anteriores a la última limpieza de datos o que llegaron con el portal cerrado no están."),
)

ch("Administración y respaldo",
 ("p", "En <b>Ajustes → Administración y respaldo</b> están las operaciones sobre el nodo conectado y los datos guardados en este navegador."),
 ("table", ["Sección", "Qué hace"], [
   ["Energía", "<b>Reiniciar</b> o <b>Apagar</b> el nodo con una demora en segundos; <b>Modo DFU</b> para cargar firmware en placas nRF52."],
   ["Hora", "<b>Sincronizar con esta PC</b> copia la hora de la computadora al nodo (útil sin GPS ni Internet)."],
   ["Sonidos", "Acceso directo a la configuración de tonos."],
   ["Lista de nodos", "Borrar nodos inactivos (sin actividad hace N días; no toca favoritos) o vaciar toda la lista."],
   ["Respaldo y restauración", "Guardar la configuración del nodo en un archivo <b>.cfg</b>, restaurarla eligiendo qué secciones aplicar, o guardar una copia dentro del nodo."],
   ["Datos del portal", "Exportar telemetría y configuración (JSON), abrir el informe imprimible de chats, exportar mensajes y borrar el historial local."]]),
 ("fig", "15b_respaldo", "Respaldo y datos del portal", []),
 ("tip", "Antes de cambiar la configuración del nodo, tocá <b>Descargar respaldo</b> y guardá el archivo .cfg en un lugar seguro. Si el archivo incluye la clave privada del nodo, tratalo como información confidencial."),
 ("warn", "<b>Borrar</b> la lista de nodos o el historial no se puede deshacer. Los nodos se vuelven a descubrir con el tiempo, pero los mensajes borrados no se recuperan."),
)

ch("Rendimiento y limpieza",
 ("p", "Si el portal se vuelve lento, esta pantalla (<b>Ajustes → Rendimiento y limpieza</b>) mide qué está pasando <b>en ese equipo</b> y permite liberar espacio sin perder lo importante."),
 ("fig", "24_rendimiento", "Medición de rendimiento", ["<b>Cuadros por segundo:</b> 60 es fluido; por debajo de 30 se nota lento. El recuadro cambia de verde a amarillo o rojo.", "<b>Nodos en la libreta:</b> cuántos nodos conoce el portal y cuántos entraron por Internet (MQTT). Es la causa más común de lentitud.", "<b>Almacenamiento usado:</b> cuánto ocupa el portal en el navegador, desglosado por tipo de dato.", "<b>Copiar diagnóstico:</b> copia todos los números como texto, para pegarlos en un mensaje o en un informe. <i>Guardar en un archivo</i> hace lo mismo en un .txt.", "<b>Olvidar nodos de Internet:</b> cada cuánto se sueltan los nodos de MQTT que ya no se escuchan."]),
 ("h3", "Por qué se pone lento"),
 ("p", "Con MQTT entran nodos de todo el país que no son de tu red. Cada nodo se dibuja, se ordena y se guarda, así que cuantos más hay, más tarda cada actualización de pantalla. El portal ahora los suelta solo: cada 5 minutos descarta los nodos que llegaron por Internet y no se escucharon en los últimos días."),
 ("note", "La limpieza <b>nunca</b> borra tu nodo, los favoritos, los nodos que te escribieron, los que tienen una alerta ni los que llegan por radio. Solo suelta los de Internet que ya no dan señal."),
 ("h3", "Qué probar si sigue lento"),
 ("steps", [
   "Cerrá las demás pestañas del navegador y volvé a medir.",
   "Desconectá los servidores MQTT que no uses (<b>Ajustes → Internet y MQTT</b>): cada uno trae el tráfico de toda la red.",
   "En el mapa, apagá las capas que no mires (rastros de movimiento, cobertura medida, vecinos).",
   "Si el almacenamiento pasa de 4 MB, tocá <b>Limpiar ahora</b>; si hace falta, borrá los datos desde Administración y respaldo (antes descargá un respaldo).",
   "Si nada alcanza, tocá <b>Copiar diagnóstico</b> y guardá ese texto: tiene todos los números necesarios para analizar el caso."]),
 ("tip", "El portal deja de dibujar el mapa y de actualizar el reloj cuando la ventana queda minimizada o tapada, así no gasta procesador de fondo."),
)

ch("Respuestas, reacciones y detalle de nodo",
 ("p", "Cada mensaje tiene un botón <b>⋯</b> en la esquina. Al tocarlo se abre un menú con reacciones rápidas y otras acciones. Todo viaja por radio con el formato estándar de la red, así que las respuestas y reacciones también se ven en las demás apps LoRa Mesh."),
 ("fig", "26_respuestas", "Mensaje con reacción 👍, respuesta citada y reacción ❤️ recibida", []),
 ("ul", ["<b>Reaccionar:</b> tocá un emoji (👍 ❤️ 😂 😮 😢 🙏 ✅ ⚠️). La reacción aparece debajo del mensaje original, no como un mensaje suelto. Si otros reaccionan con el mismo emoji se suma el contador; apoyando el mouse sobre la reacción se ve quiénes fueron.",
         "<b>Responder:</b> elegí <b>↩ Responder</b>. Arriba de la caja de texto aparece «Respondiendo a…»; escribí y enviá. Tu mensaje sale con una cita del original. Con la <b>✕</b> se cancela la respuesta.",
         "<b>Responder en privado:</b> abre un mensaje directo al autor de un mensaje de canal.",
         "<b>Copiar texto</b> copia el mensaje al portapapeles."]),
 ("h3", "Detalle de nodo"),
 ("p", "Tocando el <b>nombre o la foto</b> de quien escribió un mensaje, el nombre en la lista de nodos, el botón <b>Detalle</b> o <b>Detalle del nodo</b> en el mapa, se abre una ficha completa del nodo."),
 ("fig", "27_detalle_nodo", "Ficha de un nodo: estado, señal, posición, vecinos, rutas y acciones", []),
 ("ul", ["<b>Datos:</b> identificador, modelo, función, cuándo se lo escuchó, cómo llega (directo, por saltos o por MQTT), quién lo retransmitió, señal (SNR y RSSI), batería, uso del canal, ambiente, posición y distancia.",
         "<b>Gráficos:</b> evolución del SNR, del RSSI, de la batería y de la tensión según lo que el portal fue recibiendo.",
         "<b>Vecinos:</b> los nodos que informa escuchar (si tiene activado el módulo Información de vecinos) y los que dicen escucharlo a él.",
         "<b>Rutas medidas:</b> los últimos traceroute hacia ese nodo, ida y vuelta.",
         "<b>Acciones:</b> mensaje directo, trazar ruta, pedir posición, ver en el mapa, cómo llegar, telemetría, favorito y quitar de la lista."]),
)

ch("Avisos del celular y de la PC",
 ("p", "Además de los tonos, el portal muestra <b>avisos del sistema</b> cuando llega un mensaje y no lo estás mirando:"),
 ("ul", ["<b>En la app de Android:</b> con la app en segundo plano o la pantalla apagada aparece una notificación por conversación, que junta los últimos mensajes. Al tocarla se abre esa conversación. Hay tres tipos que se configuran aparte en Android: <i>Mensajes de canales</i>, <i>Mensajes directos y favoritos</i> (con vibración) y <i>Alertas de emergencia</i>, que suenan con el sonido de <b>alarma</b> aunque el teléfono esté en No molestar.",
         "<b>En la PC:</b> con el portal minimizado o en otra pestaña aparecen los avisos de Windows. La primera vez hay que tocar <b>Permitir avisos</b> en Ajustes → Sonidos y notificaciones.",
         "En <b>Ajustes → Sonidos y notificaciones</b> se pueden apagar los avisos o dejar solo los directos, los favoritos y las alertas. Los canales silenciados y el silencio nocturno también valen para los avisos; las alertas de emergencia se avisan siempre."]),
)

ch("GPS del celular o de la PC",
 ("p", "Si tu nodo no tiene GPS, el portal le puede pasar la ubicación del <b>celular</b> (en la app) o de la <b>computadora</b> (en el navegador). El nodo la comparte con la red como si fuera suya y aparece en el mapa de todos."),
 ("fig", "29_gps", "Ajustes → Ubicación de esta PC (en la app: GPS del celular)", []),
 ("steps", ["Entrá en <b>Ajustes → GPS del celular</b> (en la PC: <b>Ubicación de esta PC</b>).",
            "Activá <b>Compartir mi ubicación con el nodo</b> y aceptá el permiso de ubicación.",
            "Elegí cada cuánto se envía (por defecto, como máximo cada 60 segundos), cuánto tenés que moverte para que se vuelva a enviar (25 m) y cada cuánto se reenvía aunque estés quieto (15 minutos).",
            "En <b>Estado ahora</b> ves la última ubicación, su precisión y la posición que ya tiene el nodo. El botón <b>Enviar posición</b> la manda en el momento."]),
 ("warn", "Si el nodo tiene <b>GPS propio encendido</b> o una <b>posición fija</b>, va a seguir usando la suya. Para usar la del celular, en Configuración del dispositivo → Posición poné el GPS en «Desactivado» o «No presente» y desactivá la posición fija."),
 ("tip", "En la app la ubicación se sigue enviando con la pantalla apagada mientras la app esté abierta (aparece en la notificación fija). En la PC, el navegador tiene que quedar abierto."),
)

ch("Canales por código QR",
 ("p", "En <b>Configuración de radio → Canales</b>, en el recuadro <b>Compartir / importar canales</b>:"),
 ("fig", "28_qr_canales", "Código QR con los canales del nodo", []),
 ("ul", ["<b>▣ Mostrar código QR:</b> muestra un código con todos tus canales y la configuración de radio. Otro celular lo escanea y queda en la misma red. Con <b>Guardar imagen</b> se descarga como PNG para imprimirlo o mandarlo. El código es compatible con las demás apps LoRa Mesh.",
         "<b>📷 Escanear QR:</b> abre la cámara (en la app, la trasera del celular). Apuntá al código y, al leerlo, el portal pregunta si reemplaza los canales del nodo. Si no hay cámara, con <b>Elegir una foto del QR…</b> se puede usar una captura o una foto.",
         "<b>Copiar enlace</b> e <b>Importar</b> siguen funcionando igual, con el enlace en texto."]),
 ("warn", "El código QR lleva las <b>claves</b> de los canales: cualquiera que lo vea puede leer y escribir en ellos. Mostralo solo a gente de confianza."),
)

ch("Mapa sin conexión",
 ("p", "Los mapas que mirás con Internet se guardan solos. Para tener una zona completa antes de salir al campo, usá <b>Capas → ⬇ Guardar zona para usar sin conexión…</b>."),
 ("fig", "30_mapa_offline", "Descarga de una zona: radio, zooms, estimación y zonas guardadas", []),
 ("steps", ["Centrá el mapa en el lugar que te interesa y elegí en Capas el mapa base (y las superposiciones) que querés guardar.",
            "Abrí <b>Guardar zona para usar sin conexión…</b>, poné un nombre, el <b>radio</b> en kilómetros y los <b>zoom</b> mínimo y máximo. Guía: 12 = ciudad entera, 14 = barrios, 16 = calles, 17-18 = casas.",
            "Mirá la estimación de teselas y megabytes (cada nivel más de zoom multiplica por cuatro) y tocá <b>Descargar</b>. La barra muestra el avance; se puede cancelar.",
            "La zona queda en la lista de <b>Zonas guardadas</b>: <b>Ir</b> centra el mapa ahí y <b>Actualizar</b> la vuelve a bajar (solo lo que falta)."]),
 ("note", "Respetá las condiciones de uso de cada proveedor de mapas: descargá solo las zonas que vas a necesitar. Algunos proveedores no permiten guardar sus mapas; en ese caso la descarga informa cuántas teselas fallaron."),
)

ch("La aplicación para Android",
 ("p", "Además del archivo para el navegador, el portal viene como aplicación propia para celulares y tablets Android: <b>OPEN SOURCE PARIZ</b>. Es un archivo <b>.apk</b> que se instala sin pasar por Google Play y funciona en Android 7.0 o más nuevo. Tiene todo el portal (mensajes, mapa, topología, semáforo, guardia, MQTT y emergencias) y se conecta al nodo por <b>Bluetooth</b>, por <b>cable USB</b> (con adaptador OTG) o por <b>WiFi</b>."),
 ("fig", "25_app_android", "OPEN SOURCE PARIZ en el celular: conexión, mensajes con la barra inferior y menú lateral", []),
 ("h3", "Instalar una aplicación (.apk)"),
 ("steps", [
   "Copiá el archivo <b>.apk</b> al celular (por cable, por WhatsApp a vos mismo, o descargalo desde la carpeta de Drive).",
   "Abrilo desde <b>Archivos</b> o desde la notificación de descarga.",
   "Android avisa que la instalación de apps desconocidas está bloqueada: tocá <b>Configuración</b>, activá <b>Permitir de esta fuente</b> y volvé.",
   "Tocá <b>Instalar</b>. Si Google Play Protect muestra un aviso de «app no verificada», tocá <b>Más detalles → Instalar de todas formas</b>: aparece porque la app no se publicó en la tienda.",
   "Abrí la app y aceptá los permisos que pide: <b>Dispositivos cercanos</b> (Bluetooth) y <b>Notificaciones</b>. En Android 11 o anterior, en lugar de Dispositivos cercanos pide <b>Ubicación</b>, porque esas versiones la exigen para buscar equipos Bluetooth. Más adelante, solo si los usás, pide <b>Ubicación</b> (GPS del celular) y <b>Cámara</b> (escanear códigos QR)."]),
 ("h3", "Usar OPEN SOURCE PARIZ en el celular"),
 ("ul", ["<b>Barra inferior:</b> abajo de la pantalla están siempre a mano <b>Mensajes, Mapa, Topología y Nodos</b>. <b>Más</b> (o el botón ☰ de arriba) abre el menú completo con Ajustes, Configuración, canales y herramientas; el menú se desplaza con el dedo.",
         "<b>Mapa en el celular:</b> se mueve con un dedo; se acerca o aleja pellizcando, con doble toque o con los botones <b>+</b> y <b>−</b>. El botón <b>◎</b> encuadra todos los nodos. La leyenda y el panel de capas arrancan cerrados para dejar libre el mapa.",
         "<b>Bluetooth:</b> tocá <b>Bluetooth</b>; aparece la lista de nodos cercanos con su intensidad de señal. Elegí el tuyo. Si el nodo pide emparejar, ingresá el PIN que muestra su pantalla (sin pantalla suele ser 123456). <i>Mostrar todos</i> incluye equipos que no se anuncian como nodo.",
         "<b>Cable USB:</b> conectá el nodo con un adaptador <b>OTG</b> y un cable de datos. Android pregunta si abre OPEN SOURCE PARIZ: tocá <b>Aceptar</b> (podés marcar «usar siempre»). Funciona con los chips más comunes de los nodos: CP210x, CH340/CH9102 y USB nativo (ESP32-S3, nRF52/RAK4631). Los adaptadores FTDI todavía no están soportados.",
         "<b>WiFi:</b> igual que en la PC, con el celular en la misma red que el nodo.",
         "<b>MQTT sin PC:</b> la app trae el puente integrado, así que también se conecta a los servidores que solo ofrecen TCP (como el oficial) sin instalar Python.",
         "<b>En segundo plano:</b> mientras la app está abierta queda una notificación fija con el estado («Conectado a… por Bluetooth»). Así sigue recibiendo mensajes y alertas con la pantalla apagada. El botón atrás la manda al fondo sin desconectar; para cerrarla del todo usá <b>Cerrar la app</b> en esa notificación.",
         "<b>Exportar e imprimir:</b> los CSV, Excel y respaldos se guardan en <b>Descargas/OPEN SOURCE PARIZ</b> y se pueden abrir o compartir enseguida. <i>PDF / Imprimir</i> abre el servicio de impresión de Android, donde se elige <b>Guardar como PDF</b>."]),
 ("h3", "Novedades de la versión 1.2"),
 ("fig", "31_app_v12", "Versión 1.2: menú de mensaje con reacciones y ficha de nodo", []),
 ("ul", ["Avisos de Android por conversación, con sonido de alarma para las alertas de emergencia (ver «Avisos del celular y de la PC»).",
         "GPS del celular para nodos sin GPS propio (ver «GPS del celular o de la PC»).",
         "Respuestas, reacciones y ficha de nodo (ver «Respuestas, reacciones y detalle de nodo»).",
         "Código QR de canales con la cámara y descarga de zonas de mapa (ver los capítulos correspondientes)."]),
 ("tip", "Para que Android no corte la conexión con la pantalla apagada, entrá en Ajustes del teléfono → Apps → OPEN SOURCE PARIZ → Batería y elegí <b>Sin restricciones</b>."),
 ("h3", "Actualizar sin perder los datos"),
 ("p", "Para actualizar, instalá la APK nueva encima de la anterior: los mensajes, nodos y ajustes se conservan. Funciona porque todas las versiones van firmadas con la misma <b>clave de firma</b>. Esa clave se entrega aparte y hay que guardarla en un lugar seguro: si se pierde, las versiones futuras no podrán instalarse encima y habrá que desinstalar (y perder los datos guardados en el teléfono)."),
)

ch("Solución de problemas",
 ("table", ["Problema", "Qué probar"], [
   ["El navegador no muestra el botón de USB o Bluetooth.", "Abrí el portal con Chrome, Edge, Brave u Opera. En Brave, activá <b>brave://flags/#brave-web-bluetooth-api</b> y reiniciá."],
   ["No aparece el puerto USB del nodo.", "Usá un cable de datos, probá otro puerto y cerrá cualquier otro programa que esté usando el puerto."],
   ["La búsqueda de nodos en la red revisó pocas direcciones.", "En <b>Redes a revisar</b> escribiste direcciones completas en vez de los tres primeros números. Poné <b>192.168.1</b> (sin el último número) o usá el botón <b>«Revisar toda 192.168.1.x»</b> que aparece debajo del campo. El resumen al final del barrido dice cuántas direcciones revisó."],
   ["El portal no tiene las funciones nuevas.", "Estás abriendo una copia vieja del archivo. Fijate en el menú lateral, en <b>Versión del software</b>: tiene que decir la versión y la fecha. Si tenés varias copias de <b>portal-lora-mesh.html</b> en distintas carpetas, borrá las viejas. Después de reemplazar el archivo, cerrá la pestaña y abrilo de nuevo (Ctrl+F5)."],
   ["La búsqueda de nodos en la red no encuentra nada.", "Verificá que la PC y el nodo estén en la misma red, que el nodo tenga WiFi con la interfaz web activa y corregí el campo <b>Redes a revisar</b> (mirá la IP de tu PC: si empieza con 192.168.0, escribí 192.168.0). Si el nodo usa HTTPS, abrí antes https://IP en el navegador y aceptá el certificado. Si igual no aparece, escribí la IP a mano y tocá <b>Probar conexión</b>: te va a decir el motivo exacto."],
   ["Se conecta pero no llegan mensajes.", "Verificá que la <b>región</b> y el <b>preset</b> coincidan con los de los demás nodos y que haya otro nodo al alcance. Mirá la consola de tráfico."],
   ["El mensaje queda en NO ENTREGADO.", "Revisá que el nodo esté conectado y con transmisión habilitada; tocá <b>Reenviar mensaje</b>."],
   ["MQTT dice “esperando Internet”.", "La computadora no tiene Internet o no se pudo comprobar. Revisá la conexión; los mensajes quedan en cola hasta 1 hora."],
   ["Un servidor MQTT dice que solo ofrece TCP.", "Abrí el <b>puente local</b> (iniciar-puente.bat) o tocá <b>Aplicar al nodo</b>."],
   ["El botón Iniciar puente muestra la ayuda de instalación.", "Falta la instalación de una vez: ejecutá <b>instalar-boton-puente.bat</b> con los archivos en una misma carpeta, o usá <b>iniciar-puente.bat</b>. Comprobá que Python esté instalado y, si el navegador pregunta si abre “Puente OPEN SOURCE PARIZ”, tocá Abrir."],
   ["El puente no conecta.", "Ejecutá <b>python puente-mqtt.py --probar</b> para ver cuáles servidores responden; revisá el firewall o el antivirus."],
   ["No suena ningún aviso.", "Revisá el interruptor de sonidos, el volumen, el silencio nocturno y que el canal no esté silenciado. Hacé un clic en la página para habilitar el audio."],
   ["Un nodo parpadea en rojo.", "Hay una alerta de pánico sin atender o el nodo está caído. Tocá <b>Marcar atendida</b> en la barra de alertas o revisá los umbrales en Ajustes → Modo operativo y semáforo."],
   ["En la topología aparece una línea punteada.", "Es una inferencia, no una medición. Tocá <b>Trazar ruta</b> en el nodo para confirmar los tramos con un traceroute."],
   ["Un nodo no tiene líneas en la topología.", "Si llega solo por MQTT o no hay datos suficientes, se muestra en una banda aparte porque no hay enlace de radio verificado."],
   ["No veo altura en el mapa.", "El nodo informa altura 0 o no la conoce: el cuadro muestra “sin dato”."],
   ["No llegan avisos del celular.", "Revisá que la app tenga permiso de <b>Notificaciones</b>, que los avisos estén activados en Ajustes → Sonidos y notificaciones y que el canal no esté silenciado. En Ajustes del teléfono → Apps → OPEN SOURCE PARIZ → Batería elegí <b>Sin restricciones</b>."],
   ["El nodo no toma la ubicación del celular.", "El nodo tiene GPS propio encendido o posición fija: en Configuración del dispositivo → Posición poné el GPS en «Desactivado» y quitá la posición fija. Verificá que la ubicación del teléfono esté activada."],
   ["El escáner QR no abre la cámara.", "Aceptá el permiso de <b>Cámara</b>. Si no hay cámara, usá <b>Elegir una foto del QR…</b>."],
   ["La app de Android no encuentra el nodo por Bluetooth.", "Revisá que el Bluetooth del teléfono esté encendido, que la app tenga el permiso <b>Dispositivos cercanos</b> (o <b>Ubicación</b> en Android 11 o anterior, con la ubicación del teléfono activada) y que el nodo no esté conectado a otro celular. Probá <b>Mostrar todos</b>."],
   ["La app de Android no ve el cable USB.", "Usá un adaptador OTG y un cable de datos. Cuando Android pregunte si abre la app, tocá Aceptar. Los adaptadores FTDI no están soportados."],
   ["El portal se puso lento.", "Entrá en <b>Ajustes → Rendimiento y limpieza</b> y tocá <b>Medir ahora</b>. Si hay miles de nodos de Internet, usá <b>Limpiar ahora</b> y desconectá los servidores MQTT que no uses."],
   ["Perdí mis conexiones y ajustes.", "Se guardan en el navegador: si cambiaste de navegador, de equipo o borraste los datos del sitio, hay que cargarlos de nuevo."]]),
)

ch("Preguntas frecuentes y avisos",
 ("h3", "Preguntas frecuentes"),
 ("ul", ["<b>¿Necesito Internet?</b> No. La radio y todas las pantallas funcionan sin Internet; solo los mapas base y MQTT lo necesitan.",
         "<b>¿Se envía mi información a algún servidor?</b> Solo si activás MQTT y solo lo que vos publicás en los servidores que elegiste. El portal no tiene cuenta ni servidor propio.",
         "<b>¿Dónde se guardan mis datos?</b> En el navegador de tu equipo. Podés borrarlos desde Administración y respaldo.",
         "<b>¿Puedo usarlo desde el celular?</b> Sí, con Chrome en Android (Bluetooth o red). Los iPhone no permiten Bluetooth ni USB web.",
         "<b>¿Puedo compartir el portal?</b> Sí, ver el aviso de licencia."]),
 ("h3", "Licencia y avisos"),
 ("p", "Este portal incluye componentes de código abierto, entre ellos las librerías oficiales de la red LoRa Mesh, publicadas bajo la licencia <b>GPL-3.0</b>. Podés compartirlo gratuitamente; si lo distribuís, tenés que entregar también el código fuente completo y mantener la misma licencia. No se puede vender como software cerrado."),
 ("p", "El portal es un proyecto <b>independiente</b>, sin afiliación ni respaldo de las organizaciones propietarias de las marcas y servicios mencionados. Los nombres de productos y servidores pertenecen a sus respectivos dueños."),
 ("warn", "El botón de EMERGENCIAS y las comunicaciones LoRa dependen del alcance de la radio, de la energía de los equipos y de la disponibilidad de otros nodos. No garantizan la entrega de un mensaje. Usá siempre los medios oficiales de emergencia cuando estén disponibles."),
)
